"""Small-RNA stage policy; independent of the shared fastp rule's params."""

import argparse
import shlex


# fastp still rejects null/empty reads with -L. -Q also disables N-base filtering.
ADAPTER_ONLY_ARGS = '-Q -L -G'


def final_fastp_args(settings):
    if 'trim_args' in settings or settings.get('params'):
        raise ValueError('Small-RNA fastp uses only filter.trim.fastp.args for final filtering. '
                         'Remove legacy trim_args/params; adapter-only controls are generated by the workflow. '
                         'See smallrna/README.md for migration, including the explicit final length policy.')
    args = settings.get('args')
    if not isinstance(args, str) or not args.strip():
        raise ValueError('filter.trim.fastp.args must be a nonempty final-filter option string')
    _length_options(args)
    return args


def _length_options(args):
    parser = argparse.ArgumentParser(add_help=False, allow_abbrev=False)
    parser.add_argument('-l', '--length_required', type=int)
    parser.add_argument('-L', '--disable_length_filtering', action='store_true')
    options, _ = parser.parse_known_args(shlex.split(args))
    if options.length_required is None and not options.disable_length_filtering:
        raise ValueError('Small-RNA fastp args must explicitly set -l/--length_required '
                         '(NEXTflex v3: 16) or -L/--disable_length_filtering')
    if options.length_required is not None and options.disable_length_filtering:
        raise ValueError('Small-RNA fastp args cannot combine -l with -L: choose one final length policy')
    return options


def final_length_required(settings):
    """The final minimum read length of filter.trim.fastp.args, or None with -L (only empty reads are removed)."""
    return _length_options(final_fastp_args(settings)).length_required
